// Sliding window rate limiter using Redis + Lua (atomic)
import { Redis } from 'ioredis';
const redis = new Redis(process.env.REDIS_URL);

// Lua script ensures INCR + EXPIRE is atomic (no race between two commands)
const slidingWindowScript = `
  local key = KEYS[1]
  local limit = tonumber(ARGV[1])
  local window = tonumber(ARGV[2])
  local current = redis.call('INCR', key)
  if current == 1 then
    redis.call('EXPIRE', key, window)
  end
  return current
`;

async function isRateLimited(identifier, limit, windowSeconds) {
  const key = `ratelimit:${identifier}:${Math.floor(Date.now() / (windowSeconds * 1000))}`;
  const count = await redis.eval(
    slidingWindowScript, 1, key, limit, windowSeconds
  );
  return count > limit; // true → reject with 429
}

// Express middleware
function rateLimitMiddleware(limit = 100, windowSeconds = 60) {
  return async (req, res, next) => {
    const identifier = req.headers['x-api-key'] || req.ip;
    const limited = await isRateLimited(identifier, limit, windowSeconds);
    if (limited) {
      res.set('Retry-After', windowSeconds);
      return res.status(429).json({
        error: 'Rate limit exceeded',
        retryAfter: windowSeconds,
      });
    }
    res.set('X-RateLimit-Limit', limit);
    next();
  };
}

app.use('/api', rateLimitMiddleware(100, 60)); // 100 req/min

